//! Real signed grant and goal-store publication, no models or host profiles.
use super::{admission_tests::Fixture,deterministic_runtime_tests::{draft_with,queued,owned},authority::Authority,model::*,store::Store,lease_controller::Owned,criteria::{self,Certificate}};
use crate::{chat::Chat,settings::Settings};
use std::{fs,sync::Arc};
fn source(provider:&str,count:usize,extra:bool)->(Fixture,Authority,Record,Owned){
 let f=Fixture::new();let a=Authority::ensure(&f.path.join("authority")).unwrap();let mut criteria=vec![criteria::NATIVE_MESSAGE_CRITERION.into()];if extra{criteria.push("The recipient completed a different project".into());}let g=draft_with(&f,provider,criteria,count);let q=queued(&f,&a,&g);assert_eq!(q.schema_version,17);assert_eq!(q.admissions[0].spec.schema_version,5);let(g,o)=owned(&f,&a,&q,&Chat::persistent(f.path.join("main.json")));(f,a,g,o)
}
pub(super)fn send(g:&Record,o:&Owned,index:usize){
 let config=crate::pet_config::defaults();let mut settings=Settings::default();settings.active_integrations=vec!["ai_ollama".into(),"integration_spotify".into()];let p=&g.plans[0];let s=&p.steps[index];let args=super::messages::Arguments::parse(&s.operation.as_ref().unwrap().arguments).unwrap();let target=Arc::new(super::messages::Target::capture(&config,&settings,&args.to_pet_id).unwrap());let now=crate::assistant_memory::now();let r=o.review_message(g,&p.id,&s.id,format!("deliver-{index}"),target,now).unwrap();let approved=r.approve(o,g,&config,&settings,now,Arc::new(||true)).unwrap();o.send_message(g,&approved,now,||Ok((config.clone(),settings.clone()))).unwrap();
}
fn bytes(f:&Fixture,g:&Record)->Vec<u8>{fs::read(f.path.join("authority").join(format!("{}.json",g.admissions[0].spec.decision_id))).unwrap()}
#[test]fn native_completion_binds_known_criteria_before_consent_and_completes_all_original_messages_once_for_all_pets(){
 for provider in ["codex","copilot","antigravity","ollama","lmstudio","openai","integration_spotify"]{
  let(f,a,g,o)=source(provider,2,false);let row=&g.admissions[0];let b=row.spec.native_verification.as_ref().unwrap();assert_eq!(b.schema_version,2);assert!(b.matches(&g));let before=bytes(&f,&g);let p=o.verify_native_goal(&f.store(),&g).unwrap();assert!(!p.report.criteria_verified&&p.completion.is_none());assert_eq!(p.report.results[0].status,criteria::Status::Unmet);assert_eq!(bytes(&f,&g),before);
  send(&g,&o,0);let p=o.verify_native_goal(&f.store(),&g).unwrap();assert_eq!(p.report.receipts.len(),1);assert!(!p.report.criteria_verified&&p.completion.is_none());send(&g,&o,1);let charged:serde_json::Value=serde_json::from_slice(&bytes(&f,&g)).unwrap();let p=o.verify_native_goal(&f.store(),&g).unwrap();let completed=p.completion.unwrap().record;assert_eq!(completed.state,State::Completed);assert_eq!(completed.schema_version,17);let reference=completed.completion.as_ref().unwrap();assert!(reference.source.is_some()&&reference.recipe_id.is_empty()&&reference.plan_id.is_empty());assert!(!p.recipient_execution_verified);assert_eq!(p.report.receipts.len(),2);assert_eq!(reference.report_hash,p.report.content_hash().unwrap());a.verify_completed_goal(&completed).unwrap();let saved:serde_json::Value=serde_json::from_slice(&bytes(&f,&g)).unwrap();assert_eq!(saved["body"]["schemaVersion"],11);assert_eq!(saved["body"]["budgetUsage"],charged["body"]["budgetUsage"]);
  let reopened=Store::existing_verified(&f.path.join("goals"),&f.path.join("authority")).unwrap().unwrap();let loaded=reopened.read(&g.id,&g.spec.owner.pet_id).unwrap();assert_eq!(loaded.state,State::Completed);let frozen=super::reconciliation_tests::inventory(&f.path);let cert=a.certify_native_completion(&loaded).unwrap();let ack=reopened.complete_certified(&cert,crate::assistant_memory::now(),|_|panic!("ACK must not obtain live authority")).unwrap();assert_eq!(ack.status,CommitStatus::Unchanged);assert_eq!(super::reconciliation_tests::inventory(&f.path),frozen);let drain=o.drain(super::leases::DrainOutcome::Confirmed).unwrap();reopened.drain_owned(&a,&drain,crate::assistant_memory::now()).unwrap();a.verify_completed_goal(&reopened.read(&g.id,&g.spec.owner.pet_id).unwrap()).unwrap();let closed:serde_json::Value=serde_json::from_slice(&bytes(&f,&g)).unwrap();assert_eq!(closed["body"]["schemaVersion"],11);assert_eq!(closed["body"]["nativeCompletion"],saved["body"]["nativeCompletion"]);
 }
}
#[test]fn native_completion_never_maps_a_free_criterion_to_receiving_data_or_a_model_assertion(){
 let(f,a,g,o)=source("openai",1,true);send(&g,&o,0);let before=bytes(&f,&g);let p=o.verify_native_goal(&f.store(),&g).unwrap();assert_eq!(p.report.results[0].status,criteria::Status::Met);assert_eq!(p.report.results[1].status,criteria::Status::Unknown);assert!(!p.report.criteria_verified&&p.completion.is_none());assert_eq!(bytes(&f,&g),before);assert!(a.native_completion(&g.admissions[0].spec,g.admissions[0].proof.as_ref().unwrap()).unwrap().is_none());assert_eq!(f.store().read(&g.id,&g.spec.owner.pet_id).unwrap().state,State::Leased);
}
#[test]fn native_completion_recorded_evidence_cannot_cross_stop_wrong_revision_or_unrelated_goal(){
 let(f,a,g,o)=source("ollama",1,false);send(&g,&o,0);let row=&g.admissions[0];let now=crate::assistant_memory::now();let r=a.observe_native_criteria(&g,&row.spec,row.proof.as_ref().unwrap(),o.lease(),now).unwrap();assert!(r.criteria_verified);a.record_native_verification(&g,&row.spec,row.proof.as_ref().unwrap(),o.lease(),&r,now,||true).unwrap();let cert=a.certify_native_completion(&g).unwrap();let mut wrong=g.clone();wrong.spec.criteria[0]="Receiver completed work".into();assert!(cert.current(&wrong,now).is_err());a.revoke(&row.spec,row.proof.as_ref().unwrap(),now+1).unwrap();let frozen=super::reconciliation_tests::inventory(&f.path);assert!(f.store().complete_certified(&cert,now+2,|_|Ok(())).is_err());assert_eq!(super::reconciliation_tests::inventory(&f.path),frozen);assert_eq!(f.store().read(&g.id,&g.spec.owner.pet_id).unwrap().state,State::Leased);
}
#[test]fn native_completion_lost_report_and_goal_ack_reuse_exact_evidence_without_charging_again(){
 for fault in [super::authority_store::Fault::BeforeGrantPublish,super::authority_store::Fault::AfterGrantPublish]{
  let(f,mut a,g,o)=source("copilot",1,false);send(&g,&o,0);let row=&g.admissions[0];let now=crate::assistant_memory::now();let r=a.observe_native_criteria(&g,&row.spec,row.proof.as_ref().unwrap(),o.lease(),now).unwrap();let used:serde_json::Value=serde_json::from_slice(&bytes(&f,&g)).unwrap();a.fault=fault;assert!(a.record_native_verification(&g,&row.spec,row.proof.as_ref().unwrap(),o.lease(),&r,now,||true).is_err());a.fault=super::authority_store::Fault::None;let saved=a.record_native_verification(&g,&row.spec,row.proof.as_ref().unwrap(),o.lease(),&r,now+1,||true).unwrap();assert_eq!(saved,r);let progress=o.verify_native_goal(&f.store(),&g).unwrap();assert_eq!(progress.report,r);assert_eq!(progress.completion.unwrap().record.state,State::Completed);let after:serde_json::Value=serde_json::from_slice(&bytes(&f,&g)).unwrap();assert_eq!(used["body"]["budgetUsage"],after["body"]["budgetUsage"]);
 }
 for fault in [super::store::Fault::BeforePublish,super::store::Fault::AfterPublish]{
  let(f,a,g,o)=source("integration_spotify",1,false);send(&g,&o,0);let mut store=f.store();store.fault=fault;let _=o.verify_native_goal(&store,&g);store.fault=super::store::Fault::None;let loaded=store.read(&g.id,&g.spec.owner.pet_id).unwrap();let report=a.native_completion(&g.admissions[0].spec,g.admissions[0].proof.as_ref().unwrap()).unwrap().unwrap();let p=o.verify_native_goal(&store,&loaded).unwrap();assert_eq!(p.report,report);assert_eq!(p.completion.as_ref().unwrap().record.state,State::Completed);let frozen=super::reconciliation_tests::inventory(&f.path);let retained=super::native_completion_api::record_closure(p,||Err(Error::Busy));assert_eq!(retained.closure_pending,Some(Error::Busy));assert_eq!(retained.completion.unwrap().record.state,State::Completed);assert_eq!(super::reconciliation_tests::inventory(&f.path),frozen);
 }
}

#[test]fn native_completion_untrusted_report_cannot_shrink_the_reviewed_plan_or_assert_missing_receipts(){
 let(f,a,g,o)=source("openai",2,false);send(&g,&o,0);let row=&g.admissions[0];let now=crate::assistant_memory::now();let mut forged=a.observe_native_criteria(&g,&row.spec,row.proof.as_ref().unwrap(),o.lease(),now).unwrap();assert!(!forged.criteria_verified);forged.expected_messages=1;forged.criteria_verified=true;forged.results[0].status=criteria::Status::Met;forged.reference.report_hash=forged.content_hash().unwrap();let before=super::reconciliation_tests::inventory(&f.path);assert!(a.record_native_verification(&g,&row.spec,row.proof.as_ref().unwrap(),o.lease(),&forged,now,||true).is_err());assert_eq!(super::reconciliation_tests::inventory(&f.path),before);assert!(a.native_completion(&row.spec,row.proof.as_ref().unwrap()).unwrap().is_none());
}
